"""Record observed AERIS result and explicit missing comparator, never synthesize RAGAS data."""
import pathlib,hashlib,json,datetime
root=pathlib.Path(__file__).resolve().parents[1];ev=root/'evidence/flight01'
journal=json.loads((ev/'sitl-journal.json').read_text());checks=json.loads((ev/'sitl-qa.json').read_text())['checks'];assert checks and all(c['pass'] for c in checks)
config={str(p.relative_to(root)):hashlib.sha256(p.read_bytes()).hexdigest() for p in [root/'package.json',root/'runtime/sitl/arducopter',root/'runtime/sitl/copter.parm',root/'runtime/sitl/aeris.parm',root/'tools/start_sitl.sh',ev/'ab01-survey.json']}
build={str(p.relative_to(root)):hashlib.sha256(p.read_bytes()).hexdigest() for d in ['app','services'] for p in sorted((root/d).rglob('*')) if p.is_file()}
record={'scenario':'AB01-survey-flat-sitl-v1','recorded_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'world':journal['world'],'conditions':{'platform':'macOS ARM host / Linux x86_64 official ArduCopter SITL in Docker','speedup':5,'simulator':'4.7.1','home_nominal_amsl_m':10,'ground':'explicit simulated flat-world','comparable_controller_performance':False},'configuration_hashes':config,'aeris_build_hashes':build,'A':{'status':'PASS_LOCAL_SITL','journal':'sitl-journal.json','checks_passed':len(checks),'mission_items':len(journal['mission']['compiled']['items']),'readback_verified':journal['mission']['state']=='verified','execution':journal['observed']['mission']['execution'],'camera_provenance':journal['mission']['compiled']['cameraProvenance'],'physical_images_captured':False},'B':{'product':'RAGAS','status':'NOT_CHECKED','installed_apk_version':None,'binary_hash':None,'configuration':None,'results':None},'comparative_verdict':'NOT_CHECKED','scope':'A-side simulator correctness only; no RAGAS superiority, operator usability or HeraHub latency claim'}
(ev/'ab01-run.json').write_text(json.dumps(record,indent=2)+'\n');print(json.dumps({'A':record['A']['status'],'B':record['B']['status'],'checks':len(checks),'execution':record['A']['execution']['state']}))
